Item.method_code:
const {
	getState,
	itemType,
	rows,
	commandFactory,
	polySources
} = options;
const itemTypeMetadata = ArasModules.metadata.itemType;
const isPolymorphic = itemTypeMetadata.isPolymorphic(itemType.id);
const getItemType = (item) => {
	if (isPolymorphic) {
		const itemTypeId = item.itemtype;
		const itemTypeName = itemTypeMetadata.getItemTypeName(itemTypeId);
		return polySources[itemTypeName];
	}

	return itemType;
};
const { grid } = getState();
const commandAlias = target['command_alias@keyed_name'];
const promises = grid.selectedRows.map(async (rowId) => {
	const execInWin = window.execInTearOffWin(rowId, 'lock');
	if (execInWin) {
		return null;
	}

	const item = rows.get(rowId);
	const itemType = getItemType(item);
	const itemTypeName = itemType.name;
	const claimCommand = commandFactory(commandAlias, { item, itemType, itemTypeName });
	const lockEnabled = !window.isFunctionDisabled(itemTypeName, 'Lock');
	const canExecute = claimCommand.canExecute() && lockEnabled;
	if (canExecute) {
		return claimCommand.execute();
	}

	return null;
});
return Promise.allSettled(promises);
